import React, { useState, useEffect } from 'react';

// Create the RaceConditionFix component here
const RaceConditionFix = () => {
  // Initialize state variables here
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);

  // Create the fetchData function here
  const fetchData = async (id) => {
    // Simulate network delay
    await new Promise(resolve => setTimeout(resolve, 1000));
    return `Data for ID ${id}`;
  };

  // Create the handleFetch function here
  const handleFetch = async (id) => {
    setLoading(true);
    const result = await fetchData(id);
    setData(result);
    setLoading(false);
  };

  // Add useEffect with cleanup here
  useEffect(() => {
    let isMounted = true;

    return () => {
      isMounted = false;
    };
  }, []);

  return (
    <div>
      <h1>Race Condition Fix</h1>
      {/* Add button here */}
      {/* Add conditional rendering for loading and data here */}
    </div>
  );
};

export default RaceConditionFix;
